namespace ghidra.lisa.pcode.expressions;




using ghidra.lisa.pcode.contexts;
using ghidra.lisa.pcode.locations;
using ghidra.program.model.lang;
using ghidra.program.model.listing;
using ghidra.program.model.pcode;
using it.unive.lisa.analysis;
using it.unive.lisa.analysis.nonrelational.value;
using it.unive.lisa.analysis.value;
using it.unive.lisa.interprocedural;
using it.unive.lisa.program.cfg;
using it.unive.lisa.program.cfg.statement;
using it.unive.lisa.program.cfg.statement.call;
using it.unive.lisa.symbolic.value;

public class PcodeCallExpression : UnresolvedCall {

	private Function function;
	private Set<Varnode> unaffected = new();
	private Set<Varnode> killedByCall = new();

	public PcodeCallExpression(
			CFG cfg,
			CallContext ctx,
			Expression expression) : base(cfg, ctx.location(), ctx.type(), null, ctx.getCalleeName(), expression)
    {
		function = ctx.function();
		if (function != null) {
			PrototypeModel callingConvention = function.getCallingConvention();
			if (callingConvention != null) {
				Varnode[] unaffectedList = callingConvention.getUnaffectedList();
				foreach (Varnode varnode in unaffectedList) {
					unaffected.add(varnode);
				}
				Varnode[] killedByCallList = callingConvention.getKilledByCallList();
				foreach (Varnode varnode in killedByCallList) {
					killedByCall.add(varnode);
				}
			}
		}
	}

	/* @SuppressWarnings("unchecked") */
	/* @Override */
	public AnalysisState<A> forwardSemantics<A>/* where A : AbstractState<A> */(
			AnalysisState<A> entryState,
			InterproceduralAnalysis<A> interprocedural,
			StatementStore<A> expressions)
    {

		// TODO: This triggers the processing of the callee, but we effectively clears the state.
		//  We're using the slightly-sanitized entry state instead.  Quite possible, the return
		//  value from the function is being dropped here - not clear how this works.
		base.forwardSemantics(entryState, interprocedural, expressions);

		if (unaffected.isEmpty()) {
			return entryState;
		}
		if (entryState.getState() is SimpleAbstractState sas) {
			ValueDomain<object> vDomain = sas.getValueState();
			if (vDomain is ValueEnvironment vEnv) {
				if (vEnv.function == null) {
					return entryState;
				}
				foreach (object key in vEnv.function.keySet()) {
					object val = vEnv.function.get(key);
					if (key is Variable var && val is Lattice lat) {
						if (var.getCodeLocation() is PcodeLocation loc) {
							Varnode output = loc.op.getOutput();
							if (output != null &&
								output.getAddress().getAddressSpace().isRegisterSpace()) {
								if (unaffected.contains(output)) {
									continue;
								}
								if (killedByCall.contains(output)) {
									vEnv.function.put(key, lat.top());
								}
							}
						}
					}
				}
			}
		}
		return entryState;
	}
}
